import XCTest
@testable import Stello

/// Reading items back from folder files (grid part 1): FolderReader must find the same edits
/// and new items as the web's src/lib/folder-read.js. Expected results come from
/// test/fixtures/folder-read.json (FolderReadFixtures, generated by
/// scripts/make-folder-read-fixtures.mjs). Web twin: test/folder-read.test.js.
final class FolderReaderTests: XCTestCase {
    typealias W = FolderWriter
    typealias R = FolderReader

    private var fixtures: W.JSON { W.parse(FolderReadFixtures.json)! }

    private func entities(_ c: W.JSON) -> [W.Entity] {
        (c["entities"]?.array ?? []).map { e in
            W.Entity(id: e["id"]!.string!, name: e["name"]!.string!, kind: e["kind"]?.string,
                     aliases: (e["aliases"]?.array ?? []).compactMap(\.string), isPlace: e["type"]?.string == "place",
                     path: e["path"]?.string ?? "")
        }
    }

    func testEditsMatchTheWeb() {
        for c in fixtures["edits"]?.array ?? [] {
            let name = c["name"]?.string ?? "?"
            let out = R.fileEdits(c["item"]!.object!, text: c["text"]!.string!, path: c["path"]!.string!, entities: entities(c))
            let expect = c["expect"]?["fields"]
            XCTAssertEqual(out.map { R.stable(.object($0)) }, expect.map { R.stable($0) }, name)
            XCTAssertEqual(out?.keys.sorted(), expect?.object?.keys.sorted(), "fields: \(name)")
        }
    }

    func testNewItemsMatchTheWeb() {
        for c in fixtures["fresh"]?.array ?? [] {
            let name = c["name"]?.string ?? "?"
            let out = R.itemFromFile(c["text"]!.string!, path: c["path"]!.string!, entities: entities(c),
                                     modified: (c["modified"]?.number ?? 0) / 1000)
            let expect = c["expect"]
            if expect == nil || expect == .null { XCTAssertNil(out, name); continue }
            XCTAssertEqual(out?.id, expect?["id"]?.string, name)
            // Every field the web gives, with the same value (empty values compare equal).
            for k in expect?["fields"]?.object?.keys ?? [] {
                XCTAssertEqual(R.stable(out?.fields[k]), R.stable(expect?["fields"]?[k]), "\(name): \(k)")
            }
        }
    }

    func testFieldsReachSyncWireAsNumbersAndBools() {
        let fields = W.Obj([("weight", .number(1)), ("aspect", .number(1.5)), ("review", .bool(true))])
        let plain = R.plain(.object(fields)) as? [String: Any]
        XCTAssertEqual(plain?["weight"] as? Double, 1)
        XCTAssertEqual(plain?["aspect"] as? Double, 1.5)
        XCTAssertEqual(plain?["review"] as? Bool, true)
    }
}
